import{_ as s,a as o,c as a,ac as l}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第88–94课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第88–94课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第81–87课","link":"/life/english/new-concept/book-1/review-part-12"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第95–101课","link":"/life/english/new-concept/book-1/review-part-14"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第81–87课","link":"/life/english/new-concept/book-1/review-part-12"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第95–101课","link":"/life/english/new-concept/book-1/review-part-14"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-13.md","filePath":"life/english/new-concept/book-1/review-part-13.md"}'),r={name:"life/english/new-concept/book-1/review-part-13.md"};function n(t,e,i,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第88–94课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第88–94课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第88–94课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第88–94课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-88-·-现在完成时的疑问与否定" tabindex="-1">Lesson 88 · 现在完成时的疑问与否定 <a class="header-anchor" href="#lesson-88-·-现在完成时的疑问与否定" aria-label="Permalink to &quot;Lesson 88 · 现在完成时的疑问与否定 {#lesson-88-·-现在完成时的疑问与否定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Have they replaced the broken window yet?</p><h3 id="练习-1-87" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-87" aria-label="Permalink to &quot;练习 1 {#练习-1-87}&quot;">​</a></h3><p>补助动词：___ they replaced the window?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Have</p><p><strong>解析：</strong> 按本课规则判断：have/has + 过去分词表达已完成并影响现在的动作。yet 在疑问句中常译“已经”，在否定句中常译“还”。repair→repaired，break→broken；不规则过去分词不能一律加 ed。Has the mechanic repaired it? 与 He hasn&#39;t repaired it yet 对应。描述事故时先区分已经发生的事件与现在的修理状态。</p></details><p><strong>表达迁移：</strong> 围绕“询问物品修理进度”写两至三句，再读给同伴听。至少使用一次现在完成时的疑问与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Have they replaced the broken window yet? The mechanic has not repaired my bicycle yet.</p><p>Have they replaced 询问完成结果；broken 是修饰 window 的过去分词形容词，yet 询问是否已经。 Has not repaired 为现在完成时否定；yet 放句末，表示截至目前仍未完成。my bicycle 为修理对象。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-088">回看本课</a></p><h2 id="lesson-89-·-since-与-for" tabindex="-1">Lesson 89 · since 与 for <a class="header-anchor" href="#lesson-89-·-since-与-for" aria-label="Permalink to &quot;Lesson 89 · since 与 for {#lesson-89-·-since-与-for}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We have lived here for six years.</p><h3 id="练习-1-88" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-88" aria-label="Permalink to &quot;练习 1 {#练习-1-88}&quot;">​</a></h3><p>填 since/for：We have lived here ___ six years.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for</p><p><strong>解析：</strong> 按本课规则判断：现在完成时可以描述从过去延续到现在的状态。for 后接时长，如 for six years；since 后接起点，如 since 2020 或 since I moved here。问持续多久用 How long have you ...?。并非所有动词都能直接接持续时长：买到某物是瞬间事件，表达已拥有多久常用 have had，而不直接说 have bought for。</p></details><p><strong>表达迁移：</strong> 围绕“询问居住年限和持续状态”写两至三句，再读给同伴听。至少使用一次since 与 for，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We have lived here for six years. She has owned this flat since 2020.</p><p>Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。 Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-089">回看本课</a></p><h2 id="lesson-90-·-since-与-for" tabindex="-1">Lesson 90 · since 与 for <a class="header-anchor" href="#lesson-90-·-since-与-for" aria-label="Permalink to &quot;Lesson 90 · since 与 for {#lesson-90-·-since-与-for}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She has owned this flat since 2020.</p><h3 id="练习-1-89" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-89" aria-label="Permalink to &quot;练习 1 {#练习-1-89}&quot;">​</a></h3><p>填 since/for：She has owned it ___ 2020.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> since</p><p><strong>解析：</strong> 按本课规则判断：现在完成时可以描述从过去延续到现在的状态。for 后接时长，如 for six years；since 后接起点，如 since 2020 或 since I moved here。问持续多久用 How long have you ...?。并非所有动词都能直接接持续时长：买到某物是瞬间事件，表达已拥有多久常用 have had，而不直接说 have bought for。</p></details><p><strong>表达迁移：</strong> 围绕“询问居住年限和持续状态”写两至三句，再读给同伴听。至少使用一次since 与 for，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She has owned this flat since 2020. We have lived here for six years.</p><p>Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。 Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-090">回看本课</a></p><h2 id="lesson-91-·-will-表将来" tabindex="-1">Lesson 91 · will 表将来 <a class="header-anchor" href="#lesson-91-·-will-表将来" aria-label="Permalink to &quot;Lesson 91 · will 表将来 {#lesson-91-·-will-表将来}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our neighbours will move next month.</p><h3 id="练习-1-90" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-90" aria-label="Permalink to &quot;练习 1 {#练习-1-90}&quot;">​</a></h3><p>填原形：They will ___ (move) soon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> 按本课规则判断：will + 动词原形表示未来情况、预测或说话时的决定，所有人称形式相同。否定 will not 缩写为 won&#39;t；疑问把 will 提前。will be 后可接形容词或地点，但 will 后不能直接跟形容词而漏 be。与 be going to 相比，will 常用来作临时决定或一般预测，但两者并非机械互斥。</p></details><p><strong>表达迁移：</strong> 围绕“谈搬家后的未来安排”写两至三句，再读给同伴听。至少使用一次will 表将来，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our neighbours will move next month. Will the new room be ready tomorrow?</p><p>Our neighbours 为复数主语，但 will 对所有人称同形；move 用原形，next month 是将来时间。 Will 提前构成问句，the new room 为主语，be ready 构成系表结构；be 不能遗漏。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-091">回看本课</a></p><h2 id="lesson-92-·-will-表将来" tabindex="-1">Lesson 92 · will 表将来 <a class="header-anchor" href="#lesson-92-·-will-表将来" aria-label="Permalink to &quot;Lesson 92 · will 表将来 {#lesson-92-·-will-表将来}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Will the new room be ready tomorrow?</p><h3 id="练习-1-91" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-91" aria-label="Permalink to &quot;练习 1 {#练习-1-91}&quot;">​</a></h3><p>补 be：The room will ___ ready.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 按本课规则判断：will + 动词原形表示未来情况、预测或说话时的决定，所有人称形式相同。否定 will not 缩写为 won&#39;t；疑问把 will 提前。will be 后可接形容词或地点，但 will 后不能直接跟形容词而漏 be。与 be going to 相比，will 常用来作临时决定或一般预测，但两者并非机械互斥。</p></details><p><strong>表达迁移：</strong> 围绕“谈搬家后的未来安排”写两至三句，再读给同伴听。至少使用一次will 表将来，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Will the new room be ready tomorrow? Our neighbours will move next month.</p><p>Will 提前构成问句，the new room 为主语，be ready 构成系表结构；be 不能遗漏。 Our neighbours 为复数主语，但 will 对所有人称同形；move 用原形，next month 是将来时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-092">回看本课</a></p><h2 id="lesson-93-·-过去、现在与将来的时间线" tabindex="-1">Lesson 93 · 过去、现在与将来的时间线 <a class="header-anchor" href="#lesson-93-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;Lesson 93 · 过去、现在与将来的时间线 {#lesson-93-·-过去、现在与将来的时间线}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our neighbour flew to Madrid last week.</p><h3 id="练习-1-92" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-92" aria-label="Permalink to &quot;练习 1 {#练习-1-92}&quot;">​</a></h3><p>填过去式：He ___ (fly) there last week.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> flew</p><p><strong>解析：</strong> 按本课规则判断：先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p></details><p><strong>表达迁移：</strong> 围绕“比较过去经历与未来计划”写两至三句，再读给同伴听。至少使用一次过去、现在与将来的时间线，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our neighbour flew to Madrid last week. He will return next Tuesday.</p><p>Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。 Will return 为将来结构，return 用原形；next Tuesday 前不用 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-093">回看本课</a></p><h2 id="lesson-94-·-过去、现在与将来的时间线" tabindex="-1">Lesson 94 · 过去、现在与将来的时间线 <a class="header-anchor" href="#lesson-94-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;Lesson 94 · 过去、现在与将来的时间线 {#lesson-94-·-过去、现在与将来的时间线}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He will return next Tuesday.</p><h3 id="练习-1-93" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-93" aria-label="Permalink to &quot;练习 1 {#练习-1-93}&quot;">​</a></h3><p>补将来助动词：He ___ return next Tuesday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> will</p><p><strong>解析：</strong> 按本课规则判断：先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p></details><p><strong>表达迁移：</strong> 围绕“比较过去经历与未来计划”写两至三句，再读给同伴听。至少使用一次过去、现在与将来的时间线，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He will return next Tuesday. Our neighbour flew to Madrid last week.</p><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。 Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-094">回看本课</a></p>',60)])])}const g=s(r,[["render",n]]);export{m as __pageData,g as default};
